import{_ as a,o,c as t,a5 as c}from"./chunks/framework.BYIUCCsM.js";const u=JSON.parse('{"title":"常见问题","description":"","frontmatter":{},"headers":[],"relativePath":"faq.md","filePath":"faq.md","lastUpdated":1788129119000}'),d={name:"faq.md"};function r(i,e,n,s,p,l){return o(),t("div",null,[...e[0]||(e[0]=[c('<h1 id="常见问题" tabindex="-1">常见问题 <a class="header-anchor" href="#常见问题" aria-label="Permalink to &quot;常见问题&quot;">​</a></h1><h2 id="和-xihan-basicapp-的前端是什么关系" tabindex="-1">和 XiHan.BasicApp 的前端是什么关系 <a class="header-anchor" href="#和-xihan-basicapp-的前端是什么关系" aria-label="Permalink to &quot;和 XiHan.BasicApp 的前端是什么关系&quot;">​</a></h2><p>BasicApp 的前端建在 XiHan.UI 之上：自 BasicApp v4.0.0 起，它的前端整体用这套库重建。想看组件库在真实业务里怎么用，读 BasicApp 前端的源码是最快的路径。</p><p>BasicApp 的前端约定请看<a href="https://basicapp.docs.xihanfun.com/frontend/introduction" target="_blank" rel="noreferrer">基础应用前端手册</a>。</p><h2 id="到底有多少个组件" tabindex="-1">到底有多少个组件 <a class="header-anchor" href="#到底有多少个组件" aria-label="Permalink to &quot;到底有多少个组件&quot;">​</a></h2><p><strong>121 个</strong>。每个组件同时有无头内核、Vue 组件、自定义元素与默认皮肤四份产物，本文档的<a href="./components/">组件总览</a>按分类列全，每个组件一页。</p><h2 id="组件的-props-有哪些-文档里怎么没有" tabindex="-1">组件的 props 有哪些？文档里怎么没有 <a class="header-anchor" href="#组件的-props-有哪些-文档里怎么没有" aria-label="Permalink to &quot;组件的 props 有哪些？文档里怎么没有&quot;">​</a></h2><p>以 TypeScript 类型为准。<code>@xihan-ui/headless</code> 为每个组件导出 <code>XxxSchema</code>（含 <code>props</code>、<code>context</code>、<code>event</code> 等）与 <code>XxxApi</code>，编辑器里能直接跳转，注释也在类型上。</p><p>文档侧给出的是<strong>结构契约</strong>（解剖部件、必备部件、键盘表），这部分类型里读不出来，或者读起来很费劲。两边配合看。</p><h2 id="能不用默认皮肤吗" tabindex="-1">能不用默认皮肤吗 <a class="header-anchor" href="#能不用默认皮肤吗" aria-label="Permalink to &quot;能不用默认皮肤吗&quot;">​</a></h2><p>能，而且是设计上就支持的。组件只往 DOM 上打 <code>data-scope</code> / <code>data-part</code> / <code>data-state</code> 等属性，不依赖 <code>@xihan-ui/styles</code> 的任何一行。</p><p>只引令牌自己写皮肤，或者连令牌一起丢，都行。见<a href="./guide/styling#完全自己写皮肤">皮肤与样式分层</a>。</p><h2 id="支持-react-svelte-solid-吗" tabindex="-1">支持 React / Svelte / Solid 吗 <a class="header-anchor" href="#支持-react-svelte-solid-吗" aria-label="Permalink to &quot;支持 React / Svelte / Solid 吗&quot;">​</a></h2><p>目前只有 Vue 与 Web Components 两个适配器。</p><p>自定义元素在这些框架里都能直接用（Light DOM，无 Shadow DOM 封装），这是当前的通用路径。要写原生适配器的话需要三样东西：一份 <code>ReactiveRuntime</code>（五个口子）、一份 <code>NormalizeProps</code>、一层组件包装。<code>@xihan-ui/machine/vanilla</code> 是这套契约的参考实现。</p><h2 id="为什么自定义元素要我自己写-html" tabindex="-1">为什么自定义元素要我自己写 HTML <a class="header-anchor" href="#为什么自定义元素要我自己写-html" aria-label="Permalink to &quot;为什么自定义元素要我自己写 HTML&quot;">​</a></h2><p>因为它是 Light-DOM 行为宿主，不是 Shadow DOM 组件。Shadow DOM 会把结构封起来：改不了标签、插不进自己的节点、外部 CSS 进不去、表单关联与跨边界 <code>aria-*</code> 引用都要额外机制。这套库的定位是「行为可复用、外观完全由你定」。</p><p>代价就是你得写结构。漏写必备部件不会静默失败——诊断通道会明确报出来。见 <a href="./adapters/web-components">Web Components 适配器</a>。</p><h2 id="切换品牌为什么没效果" tabindex="-1">切换品牌为什么没效果 <a class="header-anchor" href="#切换品牌为什么没效果" aria-label="Permalink to &quot;切换品牌为什么没效果&quot;">​</a></h2><p>品牌轴要注册之后才换色：<code>registerBrand(id, 种子色)</code> 注入该 id 的原语取值块，切到这个品牌才有视觉变化；不注册就只是把 <code>data-brand</code> 写到 DOM 上。</p><p>明暗、对比度、密度、书写方向四条轴开箱即有取值，切了就变。见<a href="./guide/theme#五个维度各管什么">设计令牌与主题</a>。</p><h2 id="皮肤里的某条样式没生效" tabindex="-1">皮肤里的某条样式没生效 <a class="header-anchor" href="#皮肤里的某条样式没生效" aria-label="Permalink to &quot;皮肤里的某条样式没生效&quot;">​</a></h2><p>先查是不是引用了不存在的令牌名。孤儿引用不报错也不降级——整条声明在计算值阶段静默失效，CSS 不会告诉任何人。仓库里的 <code>check-token-refs</code> 门禁专门查这个。</p><p>其次查层序：按组件挑样式时必须先引 <code>@xihan-ui/styles/layers.css</code> 或 <code>@xihan-ui/tokens/tokens.css</code> 之一（两者都带完整层序声明），否则级联顺序就变成了引入顺序。</p><h2 id="浮层位置整体偏了一个滚动距离" tabindex="-1">浮层位置整体偏了一个滚动距离 <a class="header-anchor" href="#浮层位置整体偏了一个滚动距离" aria-label="Permalink to &quot;浮层位置整体偏了一个滚动距离&quot;">​</a></h2><p>坐标系不一致。机器传给定位引擎的 <code>strategy</code>、<code>connect</code> 产出的内联 <code>position</code>、皮肤里 <code>positioner</code> 规则的 <code>position</code>——三处必须写同一个值。</p><p><code>check-overlay-strategy</code> 门禁盯着这三处，但只覆盖登记在名单里的浮层组件。见<a href="./guide/position#两套坐标系">浮层定位</a>。</p><h2 id="受控组件点了没反应" tabindex="-1">受控组件点了没反应 <a class="header-anchor" href="#受控组件点了没反应" aria-label="Permalink to &quot;受控组件点了没反应&quot;">​</a></h2><p>这是预期行为。受控时组件<strong>永远不会自己动</strong>：它只发出变更意图（<code>value-change</code> / <code>open-change</code>），等你把新值写回来才真的改。</p><p>传了受控属性就必须接住变更事件并写回。只想要初值不想管后续，用 <code>default*</code> 走非受控。</p><h2 id="关闭浮层时退场动画没播完就消失了" tabindex="-1">关闭浮层时退场动画没播完就消失了 <a class="header-anchor" href="#关闭浮层时退场动画没播完就消失了" aria-label="Permalink to &quot;关闭浮层时退场动画没播完就消失了&quot;">​</a></h2><p>检查 <code>data-state</code> 的提交时机。适配器必须在 <code>data-state</code> <strong>已提交到 DOM 之后</strong>才通知进出场原语——先改属性再让 CSS 过渡起跑，顺序反了动画不会播。</p><p>用现成组件的话这条已经接好了，自己拿 <code>api</code> 渲染时要注意。</p><h2 id="诊断信息在生产环境看不到" tabindex="-1">诊断信息在生产环境看不到 <a class="header-anchor" href="#诊断信息在生产环境看不到" aria-label="Permalink to &quot;诊断信息在生产环境看不到&quot;">​</a></h2><p>默认如此。生产环境诊断阈值是 <code>silent</code>，投递直接丢弃，不产生开销。</p><p>要在生产收集，显式 <code>setDiagnosticsLevel(&#39;error&#39;)</code> 并挂自己的订阅。见<a href="./guide/diagnostics">诊断通道</a>。</p><h2 id="怎么加一个新组件" tabindex="-1">怎么加一个新组件 <a class="header-anchor" href="#怎么加一个新组件" aria-label="Permalink to &quot;怎么加一个新组件&quot;">​</a></h2><p>四份产物一起加，缺一份就是没加完：</p><ol><li><code>packages/engine/headless/src/&lt;name&gt;/</code>——解剖、状态机、<code>connect</code>、键盘规格表、元数据；</li><li><code>packages/adapters/vue/src/components/&lt;name&gt;/</code>——组件与组合式函数；</li><li><code>packages/adapters/web-components/src/elements/&lt;name&gt;.ts</code>——自定义元素，并在 <code>define.ts</code> 注册；</li><li><code>packages/design/styles/css/&lt;name&gt;.css</code>——皮肤，并在 <code>index.css</code> 引入。</li></ol><p>然后补一致性套件（<code>tooling/testing/src/suites/&lt;name&gt;.suite.ts</code>），跑 <code>pnpm test</code>、<code>pnpm test:browser</code>、<code>pnpm gate</code>、<code>pnpm boundaries</code>、<code>pnpm gate:cem</code>。</p><p>键盘规格表是先立的契约：<strong>用例通过 <code>covers</code> 反查行 id，缺一行即套件失败</strong>。</p><h2 id="无障碍问题什么时候能修完" tabindex="-1">无障碍问题什么时候能修完 <a class="header-anchor" href="#无障碍问题什么时候能修完" aria-label="Permalink to &quot;无障碍问题什么时候能修完&quot;">​</a></h2><p>没有承诺的时间表。当前状态诚实记录在<a href="./guide/a11y#存量违规登记表">无障碍与键盘规格</a>：共用表里 tag 一条、WC 侧 steps 一条，全局登记表为空，另有 breadcrumb 一条步骤重放豁免。</p><p>登记表有一条自净规则：一条都不再命中时判登记过期，修好了必须从表里删掉。</p><h2 id="还有别的问题" tabindex="-1">还有别的问题 <a class="header-anchor" href="#还有别的问题" aria-label="Permalink to &quot;还有别的问题&quot;">​</a></h2><ul><li>源码仓库：<a href="https://github.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitHub</a> · <a href="https://gitee.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">Gitee</a> · <a href="https://gitcode.com/XiHanFun/XiHan.UI" target="_blank" rel="noreferrer">GitCode</a></li><li>文档站的组件示例覆盖全部 121 个组件，且 Vue 与自定义元素两套写法并排，行为问题优先在那里复现</li></ul>',46)])])}const m=a(d,[["render",r]]);export{u as __pageData,m as default};
